//
//  SplashView.swift
//  Advent Praise
//
//  Picks up from the launch screen (LaunchBackground + LaunchLogo, the church
//  logo 160 pt wide, centred in the full screen) and reveals the app through
//  the logo: it dips a little, then its gradient fades and it grows, a
//  logo-shaped window onto the app (the Twitter reveal), zooming into the
//  book's left page until the page covers the screen. About a second,
//  critically damped. Reduce Motion: a plain cross-fade.
//
//  The outline is SDALogoShape, generated by Tools/make_splash_logo.swift with
//  LaunchLogo. Keep `Palette` in step with LaunchLogo and LaunchBackground or
//  the hand-off from the launch screen will flash.
//

import SwiftUI

/// Where the launch splash is. What's New waits for `.finished`.
enum SplashPhase: Sendable {
    /// No splash in this tree (previews, debug skip): nothing to wait for.
    case none
    case showing
    case finished
}

extension EnvironmentValues {
    @Entry var splashPhase: SplashPhase = .none
}

extension View {
    /// Covers the view with the splash once, when the window first appears.
    func splashReveal() -> some View {
        modifier(SplashReveal())
    }
}

private struct SplashReveal: ViewModifier {
    @State private var phase: SplashPhase = SplashTiming.skips ? .none : .showing
    /// The app settles from slightly enlarged as the window opens.
    @State private var contentScale: CGFloat = SplashTiming.skips ? 1 : SplashView.contentStartScale

    func body(content: Content) -> some View {
        content
            .scaleEffect(contentScale)
            .environment(\.splashPhase, phase)
            .overlay {
                if phase == .showing {
                    SplashView(contentScale: $contentScale) { phase = .finished }
                }
            }
    }
}

struct SplashView: View {
    /// LaunchLogo's size (Tools/make_splash_logo.swift).
    static let markSize = CGSize(width: 160, height: 160 / SDALogoShape.aspectRatio)
    static let contentStartScale: CGFloat = 1.06

    @Binding var contentScale: CGFloat
    var onFinished: () -> Void

    @Environment(\.colorScheme) private var colorScheme
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    @State private var scale: CGFloat = 1
    /// The logo's gradient; fading it is what opens the window.
    @State private var markOpacity: Double = 1
    @State private var opacity: Double = 1

    private var palette: Palette { colorScheme == .dark ? .dark : .light }

    var body: some View {
        GeometryReader { proxy in
            let size = proxy.size
            ZStack {
                RevealGround(markSize: Self.markSize, scale: scale)
                    .fill(palette.background, style: FillStyle(eoFill: true))
                SDALogoShape()
                    .fill(palette.gradient, style: FillStyle(eoFill: true))
                    .frame(width: Self.markSize.width, height: Self.markSize.height)
                    .opacity(markOpacity)
                    .scaleEffect(scale, anchor: SDALogoShape.revealAnchor)
            }
            .frame(width: size.width, height: size.height)
            .task { await reveal(in: size) }
        }
        .ignoresSafeArea()
        .opacity(opacity)
        .accessibilityHidden(true)
    }

    /// Big enough that the largest disc inside the logo, which stays put while
    /// the logo grows around it, clears the screen's farthest corner.
    private func coverScale(for size: CGSize) -> CGFloat {
        let anchor = RevealGround.anchorPoint(markSize: Self.markSize, in: CGRect(origin: .zero, size: size))
        let farthest = [CGPoint.zero, CGPoint(x: size.width, y: 0), CGPoint(x: 0, y: size.height),
                        CGPoint(x: size.width, y: size.height)]
            .map { hypot($0.x - anchor.x, $0.y - anchor.y) }.max()!
        return farthest / (SDALogoShape.revealRadius * Self.markSize.width) * 1.05
    }

    private func reveal(in size: CGSize) async {
        let timing = SplashTiming.self
        if reduceMotion {
            try? await Task.sleep(for: timing.seconds(0.3))
            contentScale = 1
            withAnimation(timing.animation(.easeInOut(duration: 0.4))) { opacity = 0 } completion: { onFinished() }
            return
        }
        // Hold the launch frame a beat, so the hand-off isn't felt.
        try? await Task.sleep(for: timing.seconds(0.15))
        withAnimation(timing.animation(.spring(duration: 0.3, bounce: 0))) { scale = 0.88 }
        try? await Task.sleep(for: timing.seconds(0.2))
        withAnimation(timing.animation(.easeOut(duration: 0.22))) { markOpacity = 0 }
        withAnimation(timing.animation(.spring(duration: 0.75, bounce: 0))) {
            scale = coverScale(for: size)
            contentScale = 1
        } completion: {
            onFinished()
        }
    }
}

extension SplashView {
    /// The DS tokens on the brand ground, as on the app icon: the logo runs
    /// evergreenOnDark (book, bottom-left) to brassOnDark (flame, top-right),
    /// on evergreen in light and on the Stage in dark.
    struct Palette {
        let background: Color

        var gradient: LinearGradient {
            // Stops as in Tools/make_splash_logo.swift.
            LinearGradient(stops: [.init(color: DS.Palette.evergreenOnDark, location: 0.15),
                                   .init(color: DS.Palette.brassOnDark, location: 0.85)],
                           startPoint: .bottomLeading, endPoint: .topTrailing)
        }

        static let light = Palette(background: DS.Palette.evergreen)
        static let dark = Palette(background: DS.Palette.stage)
    }
}

/// The screen with a logo-shaped hole, filled even-odd so the logo's own holes
/// (the cross, the gaps between flame strokes) stay ground. The logo is
/// centred like LaunchLogo and scaled about `SDALogoShape.revealAnchor`.
private struct RevealGround: Shape {
    var markSize: CGSize
    var scale: CGFloat

    var animatableData: CGFloat {
        get { scale }
        set { scale = newValue }
    }

    static func markRect(markSize: CGSize, in rect: CGRect) -> CGRect {
        CGRect(x: rect.midX - markSize.width / 2, y: rect.midY - markSize.height / 2,
               width: markSize.width, height: markSize.height)
    }

    static func anchorPoint(markSize: CGSize, in rect: CGRect) -> CGPoint {
        let mark = markRect(markSize: markSize, in: rect)
        return CGPoint(x: mark.minX + SDALogoShape.revealAnchor.x * mark.width,
                       y: mark.minY + SDALogoShape.revealAnchor.y * mark.height)
    }

    func path(in rect: CGRect) -> Path {
        let anchor = Self.anchorPoint(markSize: markSize, in: rect)
        let zoom = CGAffineTransform(translationX: anchor.x, y: anchor.y)
            .scaledBy(x: scale, y: scale)
            .translatedBy(x: -anchor.x, y: -anchor.y)
        var path = Path(rect)
        path.addPath(SDALogoShape().path(in: Self.markRect(markSize: markSize, in: rect)), transform: zoom)
        return path
    }
}

/// Debug launch arguments slow the splash down or skip it (see DebugLaunch).
private enum SplashTiming {
    static var skips: Bool {
        #if DEBUG
        DebugLaunch.skipsSplash
        #else
        false
        #endif
    }

    static var speed: Double {
        #if DEBUG
        DebugLaunch.splashSpeed
        #else
        1
        #endif
    }

    static func seconds(_ value: Double) -> Duration { .seconds(value / speed) }
    static func animation(_ animation: Animation) -> Animation { animation.speed(speed) }
}

